cards.css:
main {
  background: lightblue;
  padding: 40px;
}

.btn {
  padding: 10px 20px;
  background: blue;
  color: white;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.btn:hover {
  transform: translateY(-5px);
  background: darkblue;
}

/* Khusus layar sempit */
@media (max-width: 600px) {
  main {
    background: lightcoral;
    padding: 15px;
  }
}

